/// <summary>
/// Bug 222247: CB326 - Header Charges for Shrink Wrap- Volumes based charges applied incorrectly.
/// </summary>
abstract class METSalesTableTotalWeightAndVolume
{
    SalesTable salesTable;

}

Method.Source:
/// <summary>
/// Construct method
/// </summary>
/// <param name = "_salesTable">Sales order header record</param>
/// <returns>Child class instance based on SO status</returns>
public static METSalesTableTotalWeightAndVolume construct(SalesTable _salesTable)
{
    METSalesTableTotalWeightAndVolume result;

    switch (_salesTable.SalesStatus)
    {
        case (SalesStatus::None) :
        case (SalesStatus::Backorder) :
        case (SalesStatus::Canceled) :
            result = new METSalesTableTotalWeightAndVolume_Backorder(_salesTable);
            break;

        case (SalesStatus::Delivered):
        case (SalesStatus::Invoiced):
            result = new METSalesTableTotalWeightAndVolume_Delivered(_salesTable);
            break;

        default:
            throw error(strFmt("@SYS19306", funcName()));
            break;
    }

    return result;
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
void new(SalesTable _salesTable)
{
    salesTable = _salesTable;
}

/// <summary>
/// Calculation method
/// </summary>
/// <returns>Container with SO total weight and volume</returns>
public container calc()
{
    METGrossWeight  totalGrossWeight;
    METUnitVolume   totalUnitVolume;
    SalesLine       salesLine;
    METSalesLine    metSalesLine;

    while select salesLine 
           where salesLine.SalesId == salesTable.SalesId
            join metSalesLine
           where metSalesLine.SalesLine == salesLine.RecId
    {
        SalesQty qty = this.qty(salesLine);

        totalGrossWeight += qty * metSalesLine.SalesUnitWeight;
        totalUnitVolume  += qty * metSalesLine.SalesUnitVolume;
    }

    return [totalGrossWeight, totalUnitVolume];
}

/// <summary>
/// Abstract qty method defined in child classes
/// </summary>
/// <param name = "_salesLine">Sales order line record</param>
/// <returns>Ordered or delivered based on the SO status</returns>
abstract SalesQty qty(SalesLine _salesLine)
{

}

/// <summary>
/// CB326 Header charges for admin fees (Total cases)
/// For non EA lines, formula is case qty x charge amount
/// For EA lines (rare scenario), need to divide the charge amount by the sales order unit factor
/// </summary>
/// <param name = "_markupTransValue">Auto charge header charge amount</param>
/// <returns>Total cases charge amount</returns>
public MarkupValue calcTotalCasesChargeAmount(MarkupValue _markupTransValue)
{
    MarkupValue     totalCasesChargeAmount;
    METUnitVolume   totalUnitVolume;
    SalesLine       salesLine;
    METSalesLine    metSalesLine;

    while select salesLine
           where salesLine.SalesId == salesTable.SalesId
            join metSalesLine
           where metSalesLine.SalesLine == salesLine.RecId
    {
        SalesQty qty = this.qty(salesLine);

        if (salesLine.SalesUnit == METConstants::unitEach)
        {
            InventItemSalesSetup inventItemSalesSetup = InventItemSalesSetup::find(salesLine.ItemId, salesLine.InventDimId);

            if (inventItemSalesSetup && inventItemSalesSetup.METSalesUnit)
            {
                // retrieve the factor
                real factor = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(salesLine.ItemId,
                                                                                                salesLine.InventDimId,
                                                                                                1,
                                                                                                inventItemSalesSetup.METSalesUnit,
                                                                                                salesLine.SalesUnit);

                if (factor)
                {
                    totalCasesChargeAmount += qty * (_markupTransValue / factor);
                }
            }
        }
        else
        {
            totalCasesChargeAmount += qty * _markupTransValue;
        }
    }

    return totalCasesChargeAmount;
}
